select jsonb_build_object('checked_at',clock_timestamp(),'expected',count(*),'exact',count(*)filter(where exact),'mismatches',coalesce(jsonb_agg(ref)filter(where not coalesce(exact,false)),'[]')) as verification from(select 'works:1' as ref,(select to_jsonb(t) from public.works t where t.id=987158001)='{"id":987158001,"title":"Lady Windermere''s fan","cover_id":null,"author_id":977300022,"work_type":null,"source_type":"open_library","open_library_id":"OL14877416W","first_publish_year":1893,"native_identity_key":"nlscale:20261102:ol:OL14877416W"}'::jsonb as exact union all select 'editions:2' as ref,(select to_jsonb(t) from public.editions t where t.id=987258001)='{"id":987258001,"title":"Lady Windermere''s Waaier","isbn_10":null,"isbn_13":"9789077932018","work_id":987158001,"cover_id":null,"language":"dut","publisher":"Uitgeverij Diderot","publish_date":null,"open_library_edition_id":"OL12852236M"}'::jsonb as exact union all select 'catalog_work_descriptions:3' as ref,(select to_jsonb(t) from public.catalog_work_descriptions t where t.work_id=987158001 and t.language='nl')='{"text":"Lady Windermere bereidt een feest voor haar verjaardag voor wanneer zij hoort dat haar man geld geeft aan een raadselachtige vrouw. Zijn ontkenning neemt haar argwaan niet weg. Als mevrouw Erlynne vervolgens op het bal verschijnt, dreigen jaloezie en gekrenkte trots haar huwelijk te ontwrichten. Lord Darlington biedt een uitweg die nieuwe risico’s meebrengt. In deze toneelkomedie botsen de keurige regels van de Londense samenleving met wat mensen werkelijk doen. Een verloren waaier kan daarbij meer onthullen dan een openhartig gesprek.","work_id":987158001,"evidence":[{"note":"OscarWilde four-act stageplay, not novel or adaptation. ExactDutchPaperback9789077932018, confirmed sourceparent/author/KB Dutchprint. Firstprint1893 distinguished from1892stageproduction. Unsupported play type kept null under existingmodel.","type":"reviewed_identity_and_bibliography","sources":["https://data.bibl